void ULyraGameplayAbility_Interact::TriggerInteraction()
{
	if (CurrentOptions.Num() == 0)
	{
		return;
	}

	AActor* AvatarActor = GetAvatarActorFromActorInfo();
	if (!AvatarActor)
	{
		return;
	}

	FInteractionOption InteractionOption;
	if (IInteractionInstigator* Instigator = Cast<IInteractionInstigator>(AvatarActor))
	{
		FInteractionQuery Query;
		Query.RequestingAvatar = AvatarActor;
		Query.RequestingController = GetControllerFromActorInfo();
		Query.OptionalObjectData = nullptr;
		InteractionOption = Instigator->ChooseBestInteractionOption(Query, CurrentOptions);
	}
	else
	{
		InteractionOption = CurrentOptions[0];
	}

	// A valid interactable target is required before we spend any gameplay work on the interaction.
	AActor* TargetActor = UInteractionStatics::GetActorFromInteractableTarget(InteractionOption.InteractableTarget);
	if (!TargetActor)
	{
		return;
	}

	if (InteractionOption.InteractionAbilityToGrant)
	{
		UAbilitySystemComponent* ASC = GetAbilitySystemComponentFromActorInfo();
		if (!ASC)
		{
			return;
		}

		// The nearby-interaction task normally grants this ability already; fall back to granting it
		// here so that a late scan doesn't block the interaction.
		FGameplayAbilitySpecHandle AbilityToActivateHandle;
		if (FGameplayAbilitySpec* ExistingSpec = ASC->FindAbilitySpecFromClass(InteractionOption.InteractionAbilityToGrant))
		{
			AbilityToActivateHandle = ExistingSpec->Handle;
		}
		else if (ASC->GetOwnerActor() && ASC->GetOwnerActor()->HasAuthority())
		{
			FGameplayAbilitySpec SpecToGrant(InteractionOption.InteractionAbilityToGrant, 1, INDEX_NONE, InteractionOption.InteractableTarget.GetObject());
			AbilityToActivateHandle = ASC->GiveAbility(SpecToGrant);
		}
		else
		{
			return;
		}

		FGameplayEventData Payload;
		Payload.Instigator = AvatarActor;
		Payload.Target = TargetActor;

		// Let the target supplement the event data before it is delivered to the ability.
		InteractionOption.InteractableTarget->CustomizeInteractionEventData(TAG_Ability_Interaction_Activate, Payload);

		// Activating through the gameplay event preserves the GAS lifecycle and carries the payload.
		ASC->TriggerAbilityFromGameplayEvent(AbilityToActivateHandle, ASC->AbilityActorInfo.Get(), TAG_Ability_Interaction_Activate, &Payload, *ASC);
	}
	else if (InteractionOption.TargetAbilitySystem && InteractionOption.TargetInteractionAbilityHandle.IsValid())
	{
		// The target owns its ability system and the ability handle to activate.
		FGameplayEventData Payload;
		Payload.Instigator = AvatarActor;
		Payload.Target = TargetActor;

		InteractionOption.InteractableTarget->CustomizeInteractionEventData(TAG_Ability_Interaction_Activate, Payload);

		InteractionOption.TargetAbilitySystem->TriggerAbilityFromGameplayEvent(
			InteractionOption.TargetInteractionAbilityHandle,
			InteractionOption.TargetAbilitySystem->AbilityActorInfo.Get(),
			TAG_Ability_Interaction_Activate,
			&Payload,
			*InteractionOption.TargetAbilitySystem);

void ULyraGameplayAbility_Collect::ActivateAbility(const FGameplayAbilitySpecHandle Handle, const FGameplayAbilityActorInfo* ActorInfo, const FGameplayAbilityActivationInfo ActivationInfo, const FGameplayEventData* TriggerEventData)
{
	Super::ActivateAbility(Handle, ActorInfo, ActivationInfo, TriggerEventData);

	AActor* AvatarActor = ActorInfo ? ActorInfo->AvatarActor.Get() : nullptr;
	AActor* TargetActor = TriggerEventData ? const_cast<AActor*>(TriggerEventData->Target.Get()) : nullptr;
	AActor* InstigatorActor = TriggerEventData ? const_cast<AActor*>(TriggerEventData->Instigator.Get()) : nullptr;
	if (!InstigatorActor)
	{
		InstigatorActor = AvatarActor;
	}

	bool bCollected = false;

	// The server is the single authority deciding who gets the pickup.
	if (InstigatorActor && TargetActor && IsValid(TargetActor))
	{
		ULyraInventoryManagerComponent* InventoryComponent = InstigatorActor->FindComponentByClass<ULyraInventoryManagerComponent>();
		TScriptInterface<IPickupable> Pickup = UPickupableStatics::GetFirstPickupableFromActor(TargetActor);

		if (InventoryComponent && Pickup)
		{
			UPickupableStatics::AddPickupToInventory(InventoryComponent, Pickup);
			bCollected = true;

			UE_LOG(LogTemp, Log, TEXT("ULyraGameplayAbility_Collect: '%s' collected '%s' for '%s'."), *GetNameSafe(InstigatorActor), *GetNameSafe(TargetActor), *GetNameSafe(InventoryComponent));
		}
		else
		{
			UE_LOG(LogTemp, Warning, TEXT("ULyraGameplayAbility_Collect: unable to collect. Inventory=%s Pickupable=%s"), *GetNameSafe(InventoryComponent), Pickup ? TEXT("yes") : TEXT("no"));
		}
	}

	// Remove the world object so the same pickup cannot be collected twice. This is server-authoritative
	// and replicates to all clients, keeping world state consistent.
	if (bCollected)
	{
		TargetActor->Destroy();
	}

	EndAbility(Handle, ActorInfo, ActivationInfo, /*bReplicateEndAbility=*/true, /*bWasCancelled=*/false);
}

void UAbilityTask_WaitForInteractableTargets::UpdateInteractableOptions(const FInteractionQuery& InteractQuery, const TArray<TScriptInterface<IInteractableTarget>>& InteractableTargets)
{
	TArray<FInteractionOption> NewOptions;

	for (TScriptInterface<IInteractableTarget> InteractableTarget : InteractableTargets)
	{
		if (InteractableTarget.GetInterface() == nullptr)
		{
			continue;
		}

		FInteractionOptionBuilder OptionBuilder(InteractableTarget, NewOptions);
		InteractableTarget->GatherInteractionOptions(InteractQuery, OptionBuilder);
	}

	bool bOptionsChanged = false;
	if (NewOptions.Num() == CurrentOptions.Num())
	{
		NewOptions.Sort();

		for (int32 OptionIndex = 0; OptionIndex < NewOptions.Num(); OptionIndex++)
		{
			const FInteractionOption& NewOption = NewOptions[OptionIndex];
			const FInteractionOption& CurrentOption = CurrentOptions[OptionIndex];

			if (NewOption != CurrentOption)
			{
				bOptionsChanged = true;
				break;
			}
		}
	}
	else
	{
		bOptionsChanged = true;
	}

	if (bOptionsChanged)
	{
		CurrentOptions = NewOptions;
		InteractableObjectsChanged.Broadcast(CurrentOptions);

void ULyraGameplayAbility_Interact::TriggerInteraction()
{
	// The replicated input event is only intent. The server performs a fresh trace and gathers fresh options.
	if (!CurrentActorInfo || !CurrentActorInfo->IsNetAuthority() || !ScanTask) return;
	ScanTask->RefreshTargets();
	if (CurrentOptions.IsEmpty()) return;
	const FInteractionOption Option = CurrentOptions[0];
	if (!IsValid(Option.InteractableTarget.GetObject()) || !Option.InteractableTarget.GetInterface()) return;
	UAbilitySystemComponent* ASC = Option.TargetAbilitySystem;
	if (!IsValid(ASC)) return;
	FGameplayAbilitySpec* Spec = ASC->FindAbilitySpecFromHandle(Option.TargetInteractionAbilityHandle);
	if (!Spec || !Spec->Ability || !Spec->Ability->CanActivateAbility(Spec->Handle, ASC->AbilityActorInfo.Get())) return;
	FGameplayEventData Event;
	Event.EventTag = TAG_Ability_Interaction_Activate;
	Event.Instigator = GetAvatarActorFromActorInfo();
	Event.Target = UInteractionStatics::GetActorFromInteractableTarget(Option.InteractableTarget);
	Event.OptionalObject = Option.InteractableTarget.GetObject();
	Option.InteractableTarget->CustomizeInteractionEventData(TAG_Ability_Interaction_Activate, Event);
	ASC->TriggerAbilityFromGameplayEvent(Spec->Handle, ASC->AbilityActorInfo.Get(), TAG_Ability_Interaction_Activate, &Event, *ASC);

void ULyraGameplayAbility_Collect::ActivateAbility(const FGameplayAbilitySpecHandle Handle, const FGameplayAbilityActorInfo* ActorInfo, const FGameplayAbilityActivationInfo ActivationInfo, const FGameplayEventData* Event)
{
	bool bSuccess = false;
	if (ActorInfo->IsNetAuthority() && Event && ActorInfo->PlayerController.IsValid())
	{
		auto* Inventory = ActorInfo->PlayerController->FindComponentByClass<ULyraInventoryManagerComponent>();
		auto Pickup = UPickupableStatics::GetFirstPickupableFromActor(const_cast<AActor*>(Event->Target.Get()));
		if (IsValid(Event->OptionalObject.Get()) && Cast<IPickupable>(Event->OptionalObject.Get()))
			Pickup = TScriptInterface<IPickupable>(const_cast<UObject*>(Event->OptionalObject.Get()));
		if (Inventory && Pickup.GetInterface())
		{
			const int32 Before = Inventory->GetAllItems().Num();
			UPickupableStatics::AddPickupToInventory(Inventory, Pickup);
			bSuccess = Inventory->GetAllItems().Num() > Before;
		}
	}
	EndAbility(Handle, ActorInfo, ActivationInfo, true, !bSuccess);

if (!IsValid(Inventory) || !Inventory->GetOwner()->HasAuthority() || !IsValid(Pickup.GetObject()) || !Pickup.GetInterface()) return;
const FInventoryPickup Contents = Pickup->GetPickupInventory();
// Instance transfer/stack merging is deliberately outside this pickup contract.
if (Contents.Templates.IsEmpty() || !Contents.Instances.IsEmpty()) return;
for (const FPickupTemplate& Template : Contents.Templates)
{
	if (!Template.ItemDef || Template.StackCount != 1 || !Inventory->CanAddItemDefinition(Template.ItemDef, Template.StackCount))
	{
		UE_LOG(LogTemp, Warning, TEXT("Interaction: invalid pickup template on %s"), *GetNameSafe(Pickup.GetObject()));
		return;
	}
}
if (!Pickup->TryClaimPickup()) return;
for (const FPickupTemplate& Template : Contents.Templates) Inventory->AddItemDefinition(Template.ItemDef, Template.StackCount);
UE_LOG(LogTemp, Log, TEXT("Interaction: pickup committed target=%s owner=%s templates=%d"), *GetNameSafe(Pickup.GetObject()), *GetNameSafe(Inventory->GetOwner()), Contents.Templates.Num());
Pickup->OnPickupCollected();

	UAbilitySystemComponent* AbilitySystem = GetAbilitySystemComponentFromActorInfo();
	if (!AbilitySystem)
	{
		return;
	}

	const FInteractionOption& InteractionOption = CurrentOptions[0];

	AActor* Instigator = GetAvatarActorFromActorInfo();
	AActor* InteractableTargetActor = UInteractionStatics::GetActorFromInteractableTarget(InteractionOption.InteractableTarget);
	if (!InteractableTargetActor || InteractableTargetActor->IsActorBeingDestroyed()
		|| !IsValid(InteractionOption.TargetAbilitySystem) || !InteractionOption.TargetInteractionAbilityHandle.IsValid())
	{
		UE_LOG(LogLyra, Log, TEXT("Interaction: current option on %s is no longer valid, ignoring input"), *GetNameSafe(InteractableTargetActor));
		return;
	}

	// Allow the target to customize the event data we're about to pass in, in case the ability needs custom data
	// that only the actor knows.
	FGameplayEventData Payload;
	Payload.EventTag = TAG_Ability_Interaction_Activate;
	Payload.Instigator = Instigator;
	Payload.Target = InteractableTargetActor;

	// If needed we allow the interactable target to manipulate the event data so that for example, a button on the wall
	// may want to specify a door actor to execute the ability on, so it might choose to override Target to be the
	// door actor.
	InteractionOption.InteractableTarget->CustomizeInteractionEventData(TAG_Ability_Interaction_Activate, Payload);

	// Grab the target actor off the payload we're going to use it as the 'avatar' for the interaction, and the
	// source InteractableTarget actor as the owner actor.
	AActor* TargetActor = const_cast<AActor*>(ToRawPtr(Payload.Target));

	// The actor info needed for the interaction.
	FGameplayAbilityActorInfo ActorInfo;
	ActorInfo.InitFromActor(InteractableTargetActor, TargetActor, InteractionOption.TargetAbilitySystem);

	// Trigger the ability using event tag.
	const bool bSuccess = InteractionOption.TargetAbilitySystem->TriggerAbilityFromGameplayEvent(
		InteractionOption.TargetInteractionAbilityHandle,
		&ActorInfo,
		TAG_Ability_Interaction_Activate,
		&Payload,
		*InteractionOption.TargetAbilitySystem
	);

	UE_LOG(LogLyra, Log, TEXT("Interaction: trigger on %s -> %s"), *GetNameSafe(InteractableTargetActor), bSuccess ? TEXT("activated") : TEXT("rejected"));
}

void ULyraGameplayAbility_Collect::ActivateAbility(const FGameplayAbilitySpecHandle Handle, const FGameplayAbilityActorInfo* ActorInfo, const FGameplayAbilityActivationInfo ActivationInfo, const FGameplayEventData* TriggerEventData)
{
	Super::ActivateAbility(Handle, ActorInfo, ActivationInfo, TriggerEventData);

	// Only the server decides the outcome; the predicting client must not hide or grant anything.
	if (!HasAuthority(&ActivationInfo))
	{
		EndAbility(Handle, ActorInfo, ActivationInfo, /*bReplicateEndAbility=*/ false, /*bWasCancelled=*/ false);
		return;
	}

	AActor* TargetActor = TriggerEventData ? const_cast<AActor*>(ToRawPtr(TriggerEventData->Target)) : nullptr;
	TScriptInterface<IPickupable> Pickup = UPickupableStatics::GetFirstPickupableFromActor(TargetActor);
	ULyraInventoryManagerComponent* Inventory = FindInstigatorInventory();

	if (!Pickup || !Inventory || !CanCollectTarget(TargetActor))
	{
		UE_LOG(LogLyra, Log, TEXT("Collect: rejected %s for %s (pickup=%d inventory=%d)"),
			*GetNameSafe(TargetActor), *GetNameSafe(GetAvatarActorFromActorInfo()), Pickup ? 1 : 0, Inventory ? 1 : 0);
		EndAbility(Handle, ActorInfo, ActivationInfo, /*bReplicateEndAbility=*/ true, /*bWasCancelled=*/ true);
		return;
	}

	UPickupableStatics::AddPickupToInventory(Inventory, Pickup);
	OnCollected(TargetActor);

	UE_LOG(LogLyra, Log, TEXT("Collect: %s collected %s"), *GetNameSafe(GetAvatarActorFromActorInfo()), *GetNameSafe(TargetActor));

// Check if any of the options need to grant the ability to the user before they can be used.
for (FInteractionOption& Option : Options)
{
	if (Option.InteractionAbilityToGrant)
	{
		// Keyed by ability class so repeated scans never grant the same ability twice.
		FObjectKey ObjectKey(Option.InteractionAbilityToGrant);
		if (!InteractionAbilityCache.Find(ObjectKey))
		{
			// Another scan (e.g. a second interact ability instance) may already have granted it.
			if (FGameplayAbilitySpec* ExistingSpec = AbilitySystemComponent->FindAbilitySpecFromClass(Option.InteractionAbilityToGrant))
			{
				InteractionAbilityCache.Add(ObjectKey, ExistingSpec->Handle);
				continue;
			}


			FGameplayAbilitySpec Spec(Option.InteractionAbilityToGrant, 1, INDEX_NONE, this);
			FGameplayAbilitySpecHandle Handle = AbilitySystemComponent->GiveAbility(Spec);
			InteractionAbilityCache.Add(ObjectKey, Handle);
			UE_LOG(LogLyra, Log, TEXT("Interaction: granted %s to %s"), *GetNameSafe(Option.InteractionAbilityToGrant), *GetNameSafe(ActorOwner));
		}
	}
}

void ULyraInventoryGridWidget::NativeConstruct()
{
	Super::NativeConstruct();

	ListView = LyraInventoryWidgets::FindWidgetByNameOrType<UListView>(WidgetTree, ListViewName);
	InventoryComponent = ULyraInventoryWidgetStatics::FindOwningPlayerInventory(this);

	// Construct can run several times for a pooled/re-added widget; never stack listeners.
	ListenerHandle.Unregister();
	if (UWorld* World = GetWorld())
	{
		UGameplayMessageSubsystem& MessageSubsystem = UGameplayMessageSubsystem::Get(this);
		ListenerHandle = MessageSubsystem.RegisterListener(LyraInventoryWidgets::GetStackChangedChannel(), this, &ThisClass::HandleInventoryChanged);
	}

	if (!InventoryComponent)
	{
		UE_LOG(LogLyra, Warning, TEXT("InventoryGrid: no inventory found for %s"), *GetNameSafe(GetOwningPlayer()));
	}
